function saveFOLD(){var e=(new THREE.Geometry).fromBufferGeometry(globals.model.getGeometry());if(0!=e.vertices.length&&0!=e.faces.length){if(1!=globals.exportScale)for(var s=0;s<e.vertices.length;s++)e.vertices[s].multiplyScalar(globals.exportScale);var l=$("#foldFilename").val();""==l&&(l=globals.filename);var a={file_spec:1.1,file_creator:"Origami Simulator: http://git.amandaghassaei.com/OrigamiSimulator/",file_author:$("#foldAuthor").val(),file_classes:["singleModel"],frame_title:l,frame_classes:["foldedForm"],frame_attributes:["3D"],frame_unit:globals.foldUnits,vertices_coords:[],edges_vertices:[],edges_assignment:[],faces_vertices:[]};for(s=0;s<e.vertices.length;s++){var t=e.vertices[s];a.vertices_coords.push([t.x,t.y,t.z])}var r=globals.triangulateFOLDexport;if(globals.includeCurves)o=globals.curvedFolding.getFoldData(!r);else var o=globals.pattern.getFoldData(!r);a.edges_vertices=o.edges_vertices;var i=[];for(s=0;s<o.edges_assignment.length;s++)"C"==o.edges_assignment[s]?i.push("B"):i.push(o.edges_assignment[s]);a.edges_assignment=i,a.faces_vertices=o.faces_vertices,globals.exportFoldAngle&&(a.edges_foldAngle=o.edges_foldAngle);var g=new Blob([JSON.stringify(a,null,4)],{type:"application/octet-binary"});saveAs(g,l+".fold")}else globals.warn("No geometry to save.")}